PRAGMA foreign_keys = ON;
CREATE TABLE regions (id INTEGER PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL);
CREATE TABLE employees (id INTEGER PRIMARY KEY, name TEXT NOT NULL, region_id INTEGER REFERENCES regions(id));
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, segment TEXT NOT NULL, region_id INTEGER REFERENCES regions(id), account_manager_id INTEGER REFERENCES employees(id));
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE suppliers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL);
CREATE TABLE products (id INTEGER PRIMARY KEY, sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, category_id INTEGER REFERENCES categories(id), supplier_id INTEGER REFERENCES suppliers(id), price_cents INTEGER NOT NULL, cost_cents INTEGER NOT NULL);
CREATE TABLE warehouses (id INTEGER PRIMARY KEY, name TEXT NOT NULL, region_id INTEGER REFERENCES regions(id));
CREATE TABLE inventory (product_id INTEGER REFERENCES products(id), warehouse_id INTEGER REFERENCES warehouses(id), quantity INTEGER NOT NULL, reorder_point INTEGER NOT NULL, PRIMARY KEY(product_id, warehouse_id));
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), ordered_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('completed','processing','cancelled')), channel TEXT NOT NULL);
CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL, unit_price_cents INTEGER NOT NULL, unit_cost_cents INTEGER NOT NULL, discount_bps INTEGER NOT NULL);
CREATE TABLE payments (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), paid_at TEXT NOT NULL, amount_cents INTEGER NOT NULL, method TEXT NOT NULL);
CREATE TABLE shipments (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), warehouse_id INTEGER REFERENCES warehouses(id), shipped_at TEXT NOT NULL, promised_at TEXT NOT NULL, delivered_at TEXT, carrier TEXT NOT NULL);
CREATE TABLE returns (id INTEGER PRIMARY KEY, order_item_id INTEGER REFERENCES order_items(id), returned_at TEXT NOT NULL, quantity INTEGER NOT NULL, refund_cents INTEGER NOT NULL, reason TEXT NOT NULL);
CREATE TABLE tickets (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), order_id INTEGER REFERENCES orders(id), opened_at TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, subject TEXT NOT NULL);
CREATE TABLE audit_challenges (label TEXT PRIMARY KEY, secret_code TEXT NOT NULL);
CREATE INDEX idx_orders_customer_date ON orders(customer_id, ordered_at);
CREATE INDEX idx_items_order ON order_items(order_id);
CREATE INDEX idx_returns_item ON returns(order_item_id);
CREATE INDEX idx_payments_order ON payments(order_id);
CREATE INDEX idx_shipments_order ON shipments(order_id);
